from core import *
import contourpy

def unpack(out,meta,seed=31,njoint=400):
 a=meta['rotation'];rot=np.array([[np.cos(a),-np.sin(a)],[np.sin(a),np.cos(a)]]);shift=np.asarray(meta['translation']);mix=out['mdn_per_step_mixture'];means=mix.component_distribution.loc[0].numpy()@rot+shift;cov=np.einsum('ij,tmjk,kl->tmil',rot.T,mix.component_distribution.covariance_matrix[0].numpy(),rot);w=mix.mixture_distribution.probs[0].numpy();torch.manual_seed(seed);anchor=out['mdn_per_anchor_mixture'];joint=anchor.sample((njoint,))[:,0].numpy().reshape(-1,8,2)@rot+shift
 return dict(means=means,cov=cov,w=w,hypos=out['hypos'][0].numpy()@rot+shift,scores=out['hypos_prob'][0].numpy(),joint=joint,starts=np.repeat(shift[None],njoint,axis=0),anchor_weights=anchor.mixture_distribution.probs[0].numpy())

def summarize(parts,meta,gt,geometry=None,direction=1,seed=31):
 rng=np.random.default_rng(seed);K=len(parts);means=np.concatenate([p['means'] for p in parts],1);cov=np.concatenate([p['cov'] for p in parts],1);weights=np.concatenate([p['w']/K for p in parts],1);joint=np.concatenate([p['joint'] for p in parts]);scores=np.concatenate([p['scores'] for p in parts]);paths=np.concatenate([p['hypos'] for p in parts]);order=np.argsort(-scores,kind='stable')[:20];paths=paths[order];scores=scores[order];gt=np.asarray(gt);valid=np.isfinite(gt).all(1);err=np.linalg.norm(paths-gt[None],axis=-1);coverage={str(l):[] for l in [.68,.95]};area={str(l):[] for l in [.68,.95]};regions=[];nll=[]
 for t in range(8):
  m=rng.choice(means.shape[1],size=2500,p=weights[t]/weights[t].sum());samples=means[t,m]+np.einsum('nij,nj->ni',np.linalg.cholesky(cov[t,m]),rng.standard_normal((2500,2)));logp=gmm_logp(samples,means[t],cov[t],weights[t]);levels={str(l):np.quantile(logp,1-l) for l in [.68,.95]};lo=samples.min(0)-.05;hi=samples.max(0)+.05;xx=np.linspace(lo[0],hi[0],120);yy=np.linspace(lo[1],hi[1],120);X,Y=np.meshgrid(xx,yy);Z=gmm_logp(np.c_[X.ravel(),Y.ravel()],means[t],cov[t],weights[t]).reshape(120,120);contour=contourpy.contour_generator(x=xx,y=yy,z=Z);reg={};lg=float(gmm_logp(gt[t:t+1],means[t],cov[t],weights[t])[0]) if valid[t] else None;nll.append(None if lg is None else -lg)
  for l,z in levels.items():coverage[l].append(None if lg is None else bool(lg>=z));area[l].append(float((Z>=z).sum()*(xx[1]-xx[0])*(yy[1]-yy[0])));reg[l]=[s.tolist() for s in contour.lines(z)]
  regions.append(reg)
 metrics=dict(valid_GT_points=int(valid.sum()),full_4s_GT=bool(valid.all()),ADE_full4s_m=float(err[0].mean()) if valid.all() else None,FDE_top1_m=float(err[0,-1]) if valid[-1] else None,minADE_full4s_m=float(err.mean(1).min()) if valid.all() else None,minFDE20_m=float(err[:,-1].min()) if valid[-1] else None,NLL=float(np.mean([n for n in nll if n is not None])) if valid.any() else None)
 exits=dict(status='Simulation-only',model_probability_4s=None,probabilities=None,already_beyond_exit=False,GT_within4s=None)
 if geometry:
  arrivals=np.concatenate([first_exit(p['joint'],p['starts'][0],np.arange(1,9)*.5,geometry,direction) for p in parts]);exits.update(probabilities={str(h):float(np.mean(arrivals<=h)) for h in [1,2,3,4]},model_probability_4s=float(np.mean(arrivals<=4)),finite_first_exit_s=arrivals[np.isfinite(arrivals)].tolist(),sampling='official joint anchor mixture conditioned on jointly sampled observed histories')
 speed=np.linalg.norm(np.diff(np.concatenate([np.asarray(meta['translation'])[None],paths[0]]),axis=0),axis=1)/.5
 return dict(input=meta,hypotheses_xy=paths.tolist(),hypothesis_confidence_scores=scores.tolist(),hypothesis_score_sum=float(scores.sum()),hypothesis_scores_are_probabilities=False,anchor_weights=parts[0]['anchor_weights'].tolist() if K==1 else [],step_gmm=dict(means_xy=means.tolist(),covariance_m2=cov.tolist(),weights=weights.tolist()),regions=regions,coverage=coverage,area_m2=area,metrics=metrics,future_times_s=(np.arange(1,9)*.5).tolist(),representative_speed_mps=speed.tolist(),exit=exits,posterior_history_samples=K,representative_kind='highest original DD-MDN confidence among posterior history predictions; confidence not probability',joint_sample_count=len(joint))
